  double dE  = 0.0;   /* energy transfer */
  Ki = 2*PI/lambda;
  vi = K2V*fabs(Ki);
  Ei = VS2E*vi*vi;
  theta = asin(lambda/DM/2);
  A2 = theta*2;
  A1 = atan2(LME*sin(A2),(LME*cos(A2)+LMM))*RAD2DEG;
  A3 = atan2(LME*sin(A2),(LME*cos(A2)-LMM))*RAD2DEG;
  A2 *=RAD2DEG;
  A2cradle = A2;
  RV = 2*LME*sin(theta);
  if (A1<0.0) A1=180+A1;
